test('invoiceTotals preserves decimal precision', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'A', qty: 1, unitPrice: 12345, vatRate: 21, discountPercent: 2.5 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 12345
  // discount: 12345 * 2.5% = 308.625
  // base after discount: 12345 - 308.625 = 12036.375
  // vat: 12036.375 * 21% = 2527.6375 → 2528
  assert.equal(totals.subtotal, 12345);
  assert.equal(totals.discount, 308.625);
  assert.equal(totals.vat, 2528);
});

// Bulk discount tests
test('invoiceTotals applies bulk discount for qty >= 10', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000
  // line discount: 0
  // bulk discount: 10000 * 2.5% = 250
  // total discount: 250
  // vat on 9750: 9750 * 21% = 2047.5 → 2048
  // total: 10000 - 250 + 2048 = 11798
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2048);
  assert.equal(totals.total, 11798);
});

test('invoiceTotals does not apply bulk discount for qty < 10', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 9000
  // no bulk discount
  // vat on 9000: 9000 * 21% = 1890
  // total: 9000 + 1890 = 10890
  assert.equal(totals.subtotal, 9000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1890);
  assert.equal(totals.total, 10890);
});

test('invoiceTotals applies bulk discount after line discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000
  // line discount: 10000 * 10% = 1000
  // amount after line discount: 9000
  // bulk discount: 9000 * 2.5% = 225
  // total discount: 1000 + 225 = 1225
  // vat on 8775: 8775 * 21% = 1842.75 → 1843
  // total: 10000 - 1225 + 1843 = 10618
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1225);
  assert.equal(totals.vat, 1843);
  assert.equal(totals.total, 10618);
});

test('invoiceTotals with bulk discount and tier discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 5 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000
  // line discount (5% tier): 10000 * 5% = 500
  // amount after line discount: 9500
  // bulk discount: 9500 * 2.5% = 237.5
  // total discount: 500 + 237.5 = 737.5
  // vat on 9262.5: 9262.5 * 21% = 1945.125 → 1945
  // total: 10000 - 737.5 + 1945 = 11207.5
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 737.5);
  assert.equal(totals.vat, 1945);
  assert.equal(totals.total, 11207.5);
});

test('invoiceTotals with multiple lines, some with bulk discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'ITEM1', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { sku: 'ITEM2', qty: 5, unitPrice: 2000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10000, bulk discount 250, vat on 9750 = 2048
  // Line 2: 10000, no bulk discount, vat on 10000 = 2100
  // subtotal: 20000
  // discount: 250
  // vat: 4148
  // total: 20000 - 250 + 4148 = 23898
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 4148);
  assert.equal(totals.total, 23898);
});

test('invoiceTotals with all lines qualifying for bulk discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'ITEM1', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { sku: 'ITEM2', qty: 20, unitPrice: 500, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10000, bulk discount 250, vat on 9750 = 2048
  // Line 2: 10000, bulk discount 250, vat on 9750 = 2048
  // subtotal: 20000
  // discount: 500
  // vat: 4096
  // total: 20000 - 500 + 4096 = 23596
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 500);
  assert.equal(totals.vat, 4096);
  assert.equal(totals.total, 23596);
});

test('invoiceTotals bulk discount at boundary (exactly 10 units)', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 1000, vatRate: 0, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // exactly 10 units should get bulk discount
  // subtotal: 10000
  // bulk discount: 250
  // no vat
  // total: 10000 - 250 = 9750
  assert.equal(totals.discount, 250);
  assert.equal(totals.total, 9750);
});

test('invoiceTotals bulk discount not applied at boundary (9 units)', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 9, unitPrice: 1000, vatRate: 0, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // 9 units should not get bulk discount
  // subtotal: 9000
  // no discount
  // no vat
  // total: 9000
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 9000);
});

test('invoiceTotals bulk discount with 11 units', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 11, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 11000
  // bulk discount: 11000 * 2.5% = 275
  // vat on 10725: 10725 * 21% = 2252.25 → 2252
  // total: 11000 - 275 + 2252 = 12977
  assert.equal(totals.subtotal, 11000);
  assert.equal(totals.discount, 275);
  assert.equal(totals.vat, 2252);
  assert.equal(totals.total, 12977);
});

test('invoiceTotals bulk discount with large quantities', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 1000, unitPrice: 100, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 100000
  // bulk discount: 100000 * 2.5% = 2500
  // vat on 97500: 97500 * 21% = 20475
  // total: 100000 - 2500 + 20475 = 117975
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 2500);
  assert.equal(totals.vat, 20475);
  assert.equal(totals.total, 117975);
});

test('invoiceTotals bulk discount with different VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'HIGH_VAT', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { sku: 'LOW_VAT', qty: 10, unitPrice: 1000, vatRate: 9, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10000, bulk 250, vat on 9750 = 2048
  // Line 2: 10000, bulk 250, vat on 9750 = 878 (9750 * 9% = 877.5 → 878)
  // subtotal: 20000
  // discount: 500
  // vat: 2926
  // total: 20000 - 500 + 2926 = 22426
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 500);
  assert.equal(totals.vat, 2926);
  assert.equal(totals.total, 22426);
});

test('invoiceTotals bulk discount with voucher', () => {
