  // subtotal: 9000
  // no discount
  // no vat
  // total: 9000
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 9000);
});

test('invoiceTotals bulk discount with 11 units', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 11, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 11000
  // bulk discount: 11000 * 2.5% = 275
  // vat on 10725: 10725 * 21% = 2252.25 → 2252
  // total: 11000 - 275 + 2252 = 12977
  assert.equal(totals.subtotal, 11000);
  assert.equal(totals.discount, 275);
  assert.equal(totals.vat, 2252);
  assert.equal(totals.total, 12977);
});

test('invoiceTotals bulk discount with large quantities', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 1000, unitPrice: 100, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 100000
  // bulk discount: 100000 * 2.5% = 2500
  // vat on 97500: 97500 * 21% = 20475
  // total: 100000 - 2500 + 20475 = 117975
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 2500);
  assert.equal(totals.vat, 20475);
  assert.equal(totals.total, 117975);
});

test('invoiceTotals bulk discount with different VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'HIGH_VAT', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { sku: 'LOW_VAT', qty: 10, unitPrice: 1000, vatRate: 9, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10000, bulk 250, vat on 9750 = 2048
  // Line 2: 10000, bulk 250, vat on 9750 = 878 (9750 * 9% = 877.5 → 878)
  // subtotal: 20000
  // discount: 500
  // vat: 2926
  // total: 20000 - 500 + 2926 = 22426
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 500);
  assert.equal(totals.vat, 2926);
  assert.equal(totals.total, 22426);
});

test('invoiceTotals bulk discount with voucher', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
    voucher: { code: 'TEST', amount: 1000 },
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000, bulk 250, vat 2048
  // before voucher: 10000 - 250 + 2048 = 11798
  // after voucher: 11798 - 1000 = 10798
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2048);
  assert.equal(totals.total, 10798);
});

test('invoiceTotals bulk discount with line discount and voucher', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
    voucher: { code: 'TEST', amount: 500 },
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000
  // line discount: 1000
  // bulk discount: 9000 * 2.5% = 225
  // total discount: 1225
  // vat on 8775: 1843
  // before voucher: 10000 - 1225 + 1843 = 10618
  // after voucher: 10618 - 500 = 10118
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1225);
  assert.equal(totals.vat, 1843);
  assert.equal(totals.total, 10118);
});

test('invoiceTotals bulk discount calculation precision', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 333, vatRate: 21, discountPercent: 3 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 3330
  // line discount: 3330 * 3% = 99.9
  // amount after line discount: 3230.1
  // bulk discount: 3230.1 * 2.5% = 80.7525
  // total discount: 180.6525
  // vat on 3149.3475: 3149.3475 * 21% = 661.36... → 661
  // total: 3330 - 180.6525 + 661 = 3810.3475
  assert.equal(totals.subtotal, 3330);
  assert.equal(totals.discount, 180.6525);
  assert.equal(totals.vat, 661);
});

test('invoiceTotals bulk discount with zero VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 1000, vatRate: 0, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000
  // bulk discount: 250
  // no vat
  // total: 10000 - 250 = 9750
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 9750);
});

test('invoiceTotals bulk discount does not reduce below zero', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 100, vatRate: 0, discountPercent: 100 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 1000
  // line discount: 1000
  // amount after line discount: 0
  // bulk discount: 0 (since amount is already 0)
  // total discount: 1000
  // no vat
  // total: 0
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.total, 0);
});

