import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with one line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const inv = r.value;
  assert.equal(inv.customerId, 'C-001');
  assert.equal(inv.issueDate, '2026-10-07');
  assert.equal(inv.status, 'draft');
  assert.equal(inv.lines.length, 1);
  assert.equal(inv.lines[0].sku, 'DES-HOUR');
  assert.equal(inv.lines[0].name, 'Design work (hour)');
  assert.equal(inv.lines[0].qty, 5);
  assert.equal(inv.lines[0].unitPrice, 8500);
  assert.equal(inv.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID (lowercase)', () => {
  const r = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const inv = r.value;
  assert.equal(inv.customerId, 'C-001');
});

test('createInvoice normalizes customer ID (with spaces)', () => {
  const r = createInvoice({
    customerId: ' C-001 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const inv = r.value;
  assert.equal(inv.customerId, 'C-001');
});

test('createInvoice normalizes customer ID (mixed case with spaces)', () => {
  const r = createInvoice({
