test('invoiceTotals calculates discount for single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, discount: 4250, vat: 8032, voucher: 0, total: 46282 });
});

test('invoiceTotals calculates discount for multiple lines with different rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 42500 + 28500;
  const expectedDiscount = 4250 + 5700;
  const expectedVat = 8032 + 4788;
  assert.deepEqual(totals, { subtotal: expectedSubtotal, discount: expectedDiscount, vat: expectedVat, voucher: 0, total: expectedSubtotal - expectedDiscount + expectedVat });
});

