});

test('invoiceTotals includes voucher in calculation', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
    voucher: { code: 'SUMMER2026', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  // Base: 42500 - 2125 discount + 8479 VAT = 48854
  // With voucher: 48854 - 5000 = 43854
  assert.deepEqual(totals, { subtotal: 42500, discount: 2125, vat: 8479, voucher: 5000, total: 43854 });
