// Bulk discount tests
test('invoiceTotals applies bulk discount for qty >= 10', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000
  // line discount: 0
  // bulk discount: 10000 * 2.5% = 250
  // total discount: 250
  // vat on 9750: 9750 * 21% = 2047.5 → 2048
  // total: 10000 - 250 + 2048 = 11798
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2048);
  assert.equal(totals.total, 11798);
});

test('invoiceTotals does not apply bulk discount for qty < 10', () => {
  const invoice = {
