  // subtotal: 10000, bulk 250, vat 2048
  // before voucher: 10000 - 250 + 2048 = 11798
  // after voucher: 11798 - 1000 = 10798
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2048);
  assert.equal(totals.total, 10798);
});

