import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, invoiceTotals } from '../src/totals.js';

test('lineTotal calculates qty times unitPrice', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal handles various quantities', () => {
  const line1 = { sku: 'ICON-SET', qty: 10, unitPrice: 980, vatRate: 21 };
  assert.equal(lineTotal(line1), 9800);

  const line2 = { sku: 'STICKER', qty: 1000, unitPrice: 50, vatRate: 21 };
  assert.equal(lineTotal(line2), 50000);
});

test('lineTotal with zero quantity', () => {
  const line = { qty: 0, unitPrice: 8500 };
  assert.equal(lineTotal(line), 0);
});

test('lineTotal with zero unit price', () => {
  const line = { qty: 5, unitPrice: 0 };
  assert.equal(lineTotal(line), 0);
});

test('lineTotal with large numbers', () => {
  const line = { qty: 1000, unitPrice: 1000000 };
  assert.equal(lineTotal(line), 1000000000);
});

test('lineTotal with decimal quantities (edge case)', () => {
  // This tests the behavior when qty is not an integer (though the system should prevent this)
  const line = { qty: 5.5, unitPrice: 8500 };
  assert.equal(lineTotal(line), 46750);
});

test('invoiceTotals calculates discount for single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, discount: 4250, vat: 8032, voucher: 0, total: 46282 });
});

test('invoiceTotals calculates discount for multiple lines with different rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 42500 + 28500;
  const expectedDiscount = 4250 + 5700;
  const expectedVat = 8032 + 4788;
  assert.deepEqual(totals, { subtotal: expectedSubtotal, discount: expectedDiscount, vat: expectedVat, voucher: 0, total: expectedSubtotal - expectedDiscount + expectedVat });
});

test('invoiceTotals handles decimal discount percentages', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 12.5 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, discount: 5312.5, vat: 7809, voucher: 0, total: 44996.5 });
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 100 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, discount: 42500, vat: 0, voucher: 0, total: 0 });
});

test('invoiceTotals calculates subtotal and total for single line', () => {
