  };
  const totals = invoiceTotals(invoice);
  // lineAmount = 5000, discount = 500, afterDiscount = 4500, vat = 4500 * 21 / 100 = 945
  assert.deepEqual(totals, { subtotal: 5000, discount: 500, vat: 945, voucher: 0, total: 5445 });
});

test('invoiceTotals handles lines with different VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 5, unitPrice: 37, vatRate: 9, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 42500 * 21% = 8925
  // Line 2: 185 * 9% = 17 (rounded)
  assert.deepEqual(totals, { subtotal: 42685, discount: 0, vat: 8942, voucher: 0, total: 51627 });
});

test('invoiceTotals handles 0% VAT (VAT exempt)', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 60000, discount: 0, vat: 0, voucher: 0, total: 60000 });
});

test('invoiceTotals rounds VAT per line and sums', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'TEST1', name: 'Test 1', qty: 1, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { sku: 'TEST2', name: 'Test 2', qty: 1, unitPrice: 2000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 1000 * 21% = 210
  // Line 2: 2000 * 21% = 420
  // Total VAT = 630 (sum of individually rounded VATs)
  assert.deepEqual(totals, { subtotal: 3000, discount: 0, vat: 630, voucher: 0, total: 3630 });
});

test('invoiceTotals includes voucher in calculation', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
    voucher: { code: 'SUMMER2026', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  // Base: 42500 - 2125 discount + 8479 VAT = 48854
  // With voucher: 48854 - 5000 = 43854
  assert.deepEqual(totals, { subtotal: 42500, discount: 2125, vat: 8479, voucher: 5000, total: 43854 });
});

test('invoiceTotals returns voucher field (zero if none)', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
  assert.deepEqual(totals, { subtotal: 42500, discount: 2125, vat: 8479, voucher: 0, total: 48854 });
});

test('invoiceTotals clamps total to zero if voucher exceeds total', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
    voucher: { code: 'HUGE', amount: 100000 },
  };
  const totals = invoiceTotals(invoice);
  // Base: 48854, voucher: 100000 → total clamped to 0
  assert.equal(totals.total, 0);
});

test('invoiceTotals with empty lines array', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
