    status: 'draft',
    lines: [],
    voucher: { code: 'EMPTY', amount: 1000 },
  };
  const totals = invoiceTotals(invoice);
  // 0 - 0 + 0 - 1000 = -1000, clamped to 0
  assert.deepEqual(totals, { subtotal: 0, discount: 0, vat: 0, voucher: 1000, total: 0 });
