test('invoiceTotals with negative discount (edge case - should still work mathematically)', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: -10 }],
  };
  const totals = invoiceTotals(invoice);
  // Negative discount adds to the total (though this shouldn't happen in normal usage)
  // discount = -4250, so subtotal - discount = 42500 - (-4250) = 46750
  // vat on 46750 = 9817.5 → 9818
  assert.equal(totals.discount, -4250);
  assert.equal(totals.subtotal, 42500);
  assert.ok(totals.total > 42500); // Total should be higher than subtotal
});

test('invoiceTotals handles many lines', () => {
