  };
  const totals = invoiceTotals(invoice);
  // Line A: 500 - 50 = 450 base, 450 * 21% = 94.5 → 95
  // Line B: 1200 - 60 = 1140 base, 1140 * 9% = 102.6 → 103
  // Line C: 1500, no VAT
  // subtotal: 3200, discount: 110, vat: 198, total: 3288
  assert.equal(totals.subtotal, 3200);
  assert.equal(totals.discount, 110);
  assert.equal(totals.vat, 198);
  assert.equal(totals.total, 3288);
});

test('invoiceTotals does not mutate invoice', () => {
