test('invoiceTotals preserves decimal precision', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'A', qty: 1, unitPrice: 12345, vatRate: 21, discountPercent: 2.5 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 12345
  // discount: 12345 * 2.5% = 308.625
  // base after discount: 12345 - 308.625 = 12036.375
  // vat: 12036.375 * 21% = 2527.6375 → 2528
  assert.equal(totals.subtotal, 12345);
  assert.equal(totals.discount, 308.625);
  assert.equal(totals.vat, 2528);
});

// Bulk discount tests
test('invoiceTotals applies bulk discount for qty >= 10', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000
  // line discount: 0
